/**
 * Base de datos oficial de objetos de https://poke.idleworld.online
 * Extraída directamente de /game/items.json y cruzada con /game/creatures.json
 */

export interface ItemDropper {
  pokemon: string;
  id: number;
  chance: number; // porcentaje (ej. 15 = 15%)
  min: number;
  max: number;
}

export interface OfficialItem {
  id: number;
  name: string;
  icon: string;
  category: 'loot' | 'held' | 'card' | 'berry' | 'stone' | 'tm' | 'clan' | 'heal' | 'revive' | 'addon' | 'misc';
  rare: boolean;
  npcPrice: number;
  priceGold: number;
  description: string;
  healAmount: number;
  droppedBy: ItemDropper[];
}

